use super::*;
#[test]fn actual_ordered_update_lookup_closes_reset_and_forward_defining_work(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];for class in row["cursors"].as_array().unwrap(){let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let turn=SharedOwner::admit(row["key"].as_str().unwrap().to_owned(),RetainedCloneGrant{maximum_items:1,..bank}, &mut None);let(key,p)=turn.result.map_err(|(error,_)|error).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;fuel-=u64::try_from(turn.work).unwrap();assert_eq!(serde_json::to_value(&*key).unwrap(),row["key"]);let mut key=Some(key);let mut update=if class=="update"{Some(UpdateCursor::new(OrderedMap::<()>::new(),key.take().unwrap(),None))}else{None};let mut lookup=if class=="lookup"{Some(LookupCursor::new(OrderedMap::<()>::new(),key.take().unwrap()))}else{None};assert!(key.is_none());if let Some(cursor)=update.as_mut(){cursor.begin_close()}if let Some(cursor)=lookup.as_mut(){cursor.begin_close()}
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){let terminal=update.as_ref().map_or_else(||lookup.as_ref().unwrap().terminal_is_empty(),|cursor|cursor.terminal_is_empty());if terminal{break}let denied=RetainedCloneGrant{maximum_items:0,..bank};let step=if let Some(cursor)=update.as_mut(){let step=cursor.close_step(denied,fuel);assert_eq!(cursor.last_close_work(),row["deniedWork"].as_u64().unwrap());step}else{let cursor=lookup.as_mut().unwrap();let step=cursor.close_step(denied);assert_eq!(cursor.last_close_work(),row["deniedWork"].as_u64().unwrap());step};assert!(matches!(step,RetirementStep::Blocked));let((step,work),heap)=crate::allocation_testing::observe_retirement_allocations(||if let Some(cursor)=update.as_mut(){let step=cursor.close_step(RetainedCloneGrant{maximum_items:1,..bank},fuel);(step,cursor.last_close_work())}else{let cursor=lookup.as_mut().unwrap();let step=cursor.close_step(RetainedCloneGrant{maximum_items:1,..bank});(step,cursor.last_close_work())});assert!(work<=row["maximumTurnWork"].as_u64().unwrap());fuel=fuel.checked_sub(work).unwrap();assert_eq!(heap.0,0);let(items,released)=match step{RetirementStep::Progress{released_items,released_bytes}=>(released_items,released_bytes),RetirementStep::ProcessedBytes(_)=>(1,0),RetirementStep::Complete|RetirementStep::Blocked=>(0,0),RetirementStep::Failure(error)=>panic!("genuine ordered close refused: {error}"),RetirementStep::OwnedValue(_)=>panic!("empty original map has no retained payload")};assert_eq!(heap.1,released);bank.maximum_items=bank.maximum_items.checked_sub(items).unwrap();bank.maximum_release_bytes=bank.maximum_release_bytes.checked_sub(released).unwrap();}
 if let Some(cursor)=update.as_mut(){assert!(cursor.terminal_is_empty());cursor.close_step(Default::default(),fuel);assert_eq!(cursor.last_close_work(),row["cachedWork"].as_u64().unwrap())}else{let cursor=lookup.as_mut().unwrap();assert!(cursor.terminal_is_empty());cursor.close_step(Default::default());assert_eq!(cursor.last_close_work(),row["cachedWork"].as_u64().unwrap())}assert!(std::collections::BTreeMap::<String,()>::new().is_empty());}}
